toolCalls.input:
{"command": "set -u; d=$(mktemp -d); cp -r bin tests completions scripts "$d"/; cd "$d"
cat > bin/notes <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
file="${NOTES_FILE:-$HOME/.notes}"
usage() { echo "usage: notes add <text> | notes list | notes search <word>" >&2; exit 2; }
case "${1:-}" in
  add) shift; printf '%s\n' "$*" >> "$file" ;;
  list) [ -f "$file" ] && cat "$fi
